SELECT "ORDERING_REFERENCE"."ID", "ORDERING_REFERENCE"."ARTICLE_ID", "ORDERING_REFERENCE"."PROOF_ID" FROM "ORDERING_REFERENCE" INNER JOIN "ORDERING_ARTICLE" ON ("ORDERING_REFERENCE"."ARTICLE_ID" = "ORDERING_ARTICLE"."ID") LEFT OUTER JOIN "ORDERING_AUTHOR" ON ("ORDERING_ARTICLE"."AUTHOR_ID" = "ORDERING_AUTHOR"."ID") LEFT OUTER JOIN "ORDERING_AUTHOR" "T4" ON ("ORDERING_ARTICLE"."SECOND_AUTHOR_ID" = "T4"."ID") ORDER BY "ORDERING_AUTHOR"."ID" DESC, "T4"."ID" DESC;
